#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> a(n), b(n);
    for (int& x : a) cin >> x;
    for (int& x : b) cin >> x;

    int rez = 0, aSum = 0, bSum = 0;

    for (int i = 0; i < n; ++i) {
        aSum += a[i];
        bSum += b[i];
        if (a[i] == 1 && b[i] == 0) {
            ++rez;
        }
    }

    if (aSum > bSum) {
        cout << 1;
    } else if (rez == 0 || aSum == 0 || (aSum == n && bSum == n)) {
        cout << -1;
    } else {
        cout << static_cast<long long>(
            ceil(static_cast<double>(bSum - aSum + 1) / rez) + 1
        );
    }

    cout << '\n';
    return 0;
}

